globalCss:
.scene {
  --cream: #F5F2EA;
  --cream-2: #EBE5D7;
  --rule: #D5CEBE;
  --ink: #12211A;
  --ink-2: #33443B;
  --muted: #5E6D65;
  --faint: #A0A9A3;
  --green: #1E8E63;
  --green-600: #197854;
  --green-700: #145F43;
  --green-100: #EAF4F0;
  --mint: #96CAB6;
  --yellow: #F5B700;
  --yellow-200: #FDEDC0;
  --yellow-700: #A57B00;
  --blue: #1D5FA8;
  --blue-100: #EAF0F7;
  --blue-300: #96B4D6;
  --red: #D6453D;
  --red-100: #FBEDED;
  --night: #0F1A15;
  --night-2: #14231C;
  --night-rule: #2A3C33;
  --night-text: #E4EEE8;
  --night-muted: #8DA196;
  --sans: 'IBM Plex Sans', system-ui, sans-serif;
  --cond: 'IBM Plex Sans Condensed', 'IBM Plex Sans', sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, Consolas, monospace;

  position: relative;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  box-sizing: border-box;
  padding: 84px 128px 0;
  background: var(--cream);
  color: var(--ink);
  font: 400 27px/1.42 var(--sans);
  -webkit-font-smoothing: antialiased;
}
.scene *, .scene *::before, .scene *::after { box-sizing: border-box; }
.scene p, .scene h1, .scene h2, .scene h3, .scene ul, .scene ol, .scene figure, .scene dl, .scene dd, .scene pre { margin: 0; padding: 0; }
.scene ul, .scene ol { list-style: none; }
.scene b, .scene strong { font-weight: 600; }
.scene .mono { font-family: var(--mono); }
.scene .num { font-variant-numeric: tabular-nums; }

.scene.tone-dark { background: var(--night); color: var(--night-text); }
.scene.tone-green { background: var(--green); color: #fff; }

/* --- header: the five parts of the assignment, then the title ----------- */
/* The top right corner stays empty: the speaker card lands there. */
.scene .parts { display: flex; gap: 40px; font: 500 18px/1 var(--sans); color: var(--faint); }
.scene .parts span { position: relative; padding-bottom: 12px; white-space: nowrap; }
.scene .parts b { font-family: var(--cond); font-weight: 600; margin-right: 8px; }
.scene .parts .on { color: var(--ink); }
.scene .parts .on::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: var(--green); }
.scene.tone-dark .parts { color: #56695E; }
.scene.tone-dark .parts .on { color: var(--night-text); }
.scene.tone-dark .parts .on::after { background: var(--mint); }
.scene .title { margin-top: 32px; max-width: 1180px; font: 600 64px/1.06 var(--sans); letter-spacing: -.012em; }

/* Content area: same top on every scene. */
.scene .body { position: absolute; left: 128px; right: 128px; top: 272px; bottom: 72px; }
.scene .grid12 { display: grid; grid-template-columns: repeat(12, 1fr); column-gap: 32px; }
.scene .label { font: 500 19px/1.2 var(--sans); color: var(--muted); }
.scene.tone-dark .label { color: var(--night-muted); }
.scene .note { position: absolute; left: 128px; bottom: 40px; font: 400 19px/1.3 var(--sans); color: var(--muted); }
.scene.tone-dark .note { color: var(--night-muted); }
.scene mark { background: none; color: inherit; box-shadow: inset 0 -.38em 0 var(--yellow-200); padding: 0 .06em; }
.scene.tone-dark mark, .scene.tone-green mark { box-shadow: none; color: var(--yellow); }
.scene .sq { display: inline-block; width: 14px; height: 14px; margin-right: 12px; vertical-align: 1px; }
.scene .sq.upd { background: var(--yellow); }
.scene .sq.new { background: var(--green); }
.scene .tick { display: inline-block; width: .9em; height: .9em; vertical-align: -.1em; }

/* --- figures ------------------------------------------------------------- */
.scene .fig-stage {
  position: absolute;
  left: 128px;
  right: 128px;
  top: 272px;
  bottom: 168px;
  border-radius: 6px;
  overflow: hidden;
  background: #fff;
  box-shadow: inset 0 0 0 1px var(--rule);
}
.scene .fig-stage.on-dark { background: #1E1E1E; box-shadow: inset 0 0 0 1px var(--night-rule); }
.scene .fig-stage.on-cream { background: var(--cream-2); }
/* With a legend: legend takes four columns, the figure the other eight. */
.scene .fig-stage.with-legend { left: 693px; bottom: 72px; }
.scene .fig-canvas { position: absolute; left: 0; top: 0; transform-origin: 0 0; }
.scene .fig-canvas > img { display: block; width: 100%; height: 100%; }
.scene .focus { position: absolute; display: block; pointer-events: none; }
.scene .mark { position: absolute; display: block; border-radius: .4%; box-shadow: 0 0 0 var(--ring, 8px) var(--yellow); }
.scene .fig-caption {
  position: absolute;
  left: 128px;
  right: 128px;
  bottom: 56px;
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  column-gap: 32px;
  font: 400 21px/1.35 var(--sans);
}
.scene .fig-caption > p { grid-column: span 4; padding-top: 16px; border-top: 1px solid var(--rule); }
.scene.tone-dark .fig-caption > p { border-top-color: var(--night-rule); }
.scene .fig-caption b { display: block; margin-bottom: 4px; font-weight: 600; }
.scene .fig-caption .muted { color: var(--muted); }
.scene.tone-dark .fig-caption .muted { color: var(--night-muted); }
.scene .legend {
  position: absolute;
  left: 128px;
  top: 272px;
  bottom: 72px;
  width: 533px;
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--ink);
}
.scene .legend li { flex: 1; display: grid; grid-template-columns: 48px 1fr; align-items: center; column-gap: 8px; border-bottom: 1px solid var(--rule); }
.scene .legend .n { font: 600 30px/1 var(--cond); color: var(--green); }
.scene .legend b { display: block; font: 600 24px/1.2 var(--sans); }
.scene .legend span.t { display: block; margin-top: 4px; font: 400 20px/1.32 var(--sans); color: var(--muted); }
.scene .legend .risk .n { color: var(--red); }
.scene .legend .total { background: var(--blue); color: #fff; border-bottom: 0; padding: 0 24px; margin-top: 16px; flex: 1.15; grid-template-columns: 1fr; }
.scene .legend .total b { font: 600 52px/1 var(--cond); }
.scene .legend .total span.t { color: #DCE6F2; font-size: 21px; }

/* --- 01 capa ------------------------------------------------------------ */
.s-cover .brand { display: flex; align-items: center; gap: 16px; font: 600 24px/1 var(--sans); }
.s-cover .brand svg { width: 46px; height: 32px; }
.s-cover .display { margin-top: 112px; font: 600 240px/.86 var(--cond); letter-spacing: -.02em; }
.s-cover .lead { margin-top: 40px; font: 500 48px/1.15 var(--sans); }
.s-cover .sub { margin-top: 24px; max-width: 1040px; font: 400 27px/1.42 var(--sans); color: #DDF0E7; }
.s-cover .team { position: absolute; left: 128px; right: 128px; bottom: 64px; display: grid; grid-template-columns: repeat(5, 1fr); column-gap: 32px; padding-top: 32px; border-top: 1px solid rgba(255, 255, 255, .3); }
.scene .member { display: flex; align-items: center; gap: 16px; }
.scene .member img { width: 88px; height: 88px; border-radius: 50%; border: 3px solid var(--yellow); flex: none; }
.scene .member figcaption { font: 600 21px/1.25 var(--sans); }
.scene .member small { display: block; margin-top: 8px; font: 400 17px/1 var(--mono); color: #CFEBDD; }

/* --- 02 o que mudou ----------------------------------------------------- */
.s-evolucao .left { grid-column: 1 / span 5; display: flex; flex-direction: column; }
.s-evolucao .recap { color: var(--ink-2); max-width: 560px; }
.s-evolucao .recap .label { display: block; margin-bottom: 8px; }
.s-evolucao .statement { margin-top: 96px; font: 500 40px/1.26 var(--sans); }
.s-evolucao .ledger { grid-column: 7 / span 6; font-size: 25px; line-height: 1.35; }
.s-evolucao .row { display: grid; grid-template-columns: 184px 216px 1fr; column-gap: 24px; padding: 32px 0; border-bottom: 1px solid var(--rule); }
.s-evolucao .row.th { padding: 0 0 16px; border-bottom: 1px solid var(--ink); font: 500 19px/1.2 var(--sans); color: var(--muted); }
.s-evolucao .row .what { font-weight: 600; }
.s-evolucao .row .before { color: var(--muted); }
.s-evolucao .row .after b { color: var(--green-700); }
.s-evolucao .row.db .after b { color: var(--blue); }

/* --- 03 regras ---------------------------------------------------------- */
.s-regras .scenario { grid-column: 1 / span 6; }
.s-regras .panel { margin-top: 16px; border-radius: 6px; background: #fff; box-shadow: inset 0 0 0 1px var(--rule); }
.s-regras .panel-head { display: flex; justify-content: space-between; padding: 20px 24px; border-bottom: 1px solid var(--rule); font: 600 22px/1 var(--sans); }
.s-regras .panel-head .mono { font-weight: 500; }
.s-regras dl { display: grid; grid-template-columns: 200px 1fr; row-gap: 16px; padding: 32px 24px; font-size: 26px; }
.s-regras dt { color: var(--muted); }
.s-regras dd { font-weight: 600; }
.s-regras dd.dest { color: var(--green-700); }
.s-regras .slots { margin-top: 32px; border-top: 1px solid var(--ink); }
.s-regras .slots li { display: grid; grid-template-columns: 200px 1fr auto; align-items: center; column-gap: 16px; height: 80px; border-bottom: 1px solid var(--rule); font-size: 24px; }
.s-regras .slots .mono { font-size: 22px; }
.s-regras .slots .st { font-size: 20px; color: var(--green-700); font-weight: 500; }
.s-regras .slots li.out { color: var(--faint); }
.s-regras .slots li.out .unit { text-decoration: line-through; text-decoration-thickness: 2px; text-decoration-color: var(--red); }
.s-regras .slots li.out .st { color: var(--red); }
.s-regras .rules { grid-column: 8 / span 5; border-top: 1px solid var(--ink); }
.s-regras .rules li { display: grid; grid-template-columns: 64px 1fr; padding: 32px 0; border-bottom: 1px solid var(--rule); }
.s-regras .rules .n { font: 600 44px/1 var(--cond); color: var(--green); }
.s-regras .rules p { font: 600 30px/1.22 var(--sans); }
.s-regras .rules small { display: block; margin-top: 8px; font: 400 21px/1.3 var(--sans); color: var(--muted); }

/* --- 04 testes e demo --------------------------------------------------- */
.s-demo .col-a { grid-column: 1 / span 6; }
.s-demo .col-b { grid-column: 7 / span 6; }
.s-demo .term {
  margin-top: 16px;
  padding: 24px 28px;
  border-radius: 6px;
  background: #0A1410;
  box-shadow: inset 0 0 0 1px var(--night-rule);
  font: 400 19px/1.7 var(--mono);
  color: #C9DBD1;
  white-space: pre-wrap;
}
.s-demo .ln { position: relative; display: block; padding: 0 8px; margin: 0 -8px; }
.s-demo .ln .hl { position: absolute; inset: 0; border-radius: 3px; background: rgba(245, 183, 0, .17); }
.s-demo .ln .t { position: relative; }
.s-demo .ok { color: #7FD1A9; }
.s-demo .err { color: #F0A39D; }
.s-demo .dim { color: #6E8478; }
.s-demo .sum { color: #7FD1A9; font-weight: 500; }
.s-demo .tick { color: #7FD1A9; }
.s-demo .closing { position: absolute; left: 0; right: 0; bottom: 0; padding-top: 24px; border-top: 1px solid var(--night-rule); font: 400 30px/1.3 var(--sans); }
.s-demo .closing strong { color: var(--yellow); font-weight: 600; }

/* --- 05 UML ------------------------------------------------------------- */
.s-uml .col { grid-column: span 6; display: flex; flex-direction: column; gap: 32px; }
.s-uml .group { font: 600 22px/1 var(--sans); padding-bottom: 16px; border-bottom: 1px solid var(--ink); }
.s-uml .shot { height: 248px; border-radius: 6px; overflow: hidden; background: #121212; }
.s-uml .shot img { width: 100%; height: 100%; object-fit: cover; display: block; }
.s-uml figcaption { margin-top: 16px; font-size: 22px; line-height: 1.3; color: var(--muted); }
.s-uml figcaption b { color: var(--ink); margin-right: 8px; }

/* --- 08 números do modelo lógico ---------------------------------------- */
.s-numeros .counts { grid-column: 1 / span 7; display: grid; grid-template-columns: repeat(3, 1fr); align-self: center; border-top: 1px solid var(--ink); }
.s-numeros .count { padding: 32px 32px 0 0; }
.s-numeros .count + .count { padding-left: 32px; border-left: 1px solid var(--rule); }
.s-numeros .count b { display: block; font: 600 180px/.9 var(--cond); letter-spacing: -.02em; color: var(--blue); }
.s-numeros .count span { display: block; margin-top: 24px; font: 600 30px/1.1 var(--sans); }
.s-numeros .count small { display: block; margin-top: 8px; font: 400 20px/1.35 var(--sans); color: var(--muted); }
.s-numeros .grid12 { height: 100%; }
.s-numeros .nav { grid-column: 9 / span 4; display: flex; flex-direction: column; }
.s-numeros .nav-frame { position: relative; height: 640px; aspect-ratio: 1069 / 1501; border-radius: 6px; overflow: hidden; box-shadow: inset 0 0 0 1px var(--rule); }
.s-numeros .nav-frame img { width: 100%; height: 100%; display: block; }
.s-numeros .nav-frame .mark { --ring: 3px; border-radius: 2px; }
.s-numeros .nav .label { margin-top: 16px; }

/* --- 10 tabela única ---------------------------------------------------- */
.s-tabela .tbl { border-top: 1px solid var(--ink); }
.s-tabela .row {
  position: relative;
  display: grid;
  grid-template-columns: 148px 120px 196px 316px 200px 320px 1fr;
  height: 76px;
  border-bottom: 1px solid var(--rule);
  font: 400 21px/1 var(--mono);
}
.s-tabela .row > span { position: relative; display: flex; align-items: center; gap: 8px; padding-right: 16px; white-space: nowrap; }
.s-tabela .row.th { height: 48px; font: 500 16px/1 var(--mono); color: var(--muted); border-bottom-color: var(--ink); }
.s-tabela .row.ghost { color: var(--faint); border-bottom: 0; }
.s-tabela .row.ghost .q { color: var(--red); font-weight: 600; }
.s-tabela .ov { position: absolute; display: flex; align-items: center; pointer-events: none; }
.s-tabela .ov-ghost { inset: 6px -12px; border: 2px dashed var(--red); border-radius: 6px; justify-content: flex-end; padding-right: 16px; font: 500 18px/1 var(--sans); color: var(--red); }
.s-tabela .ov-del { inset: 0 -12px; background: rgba(214, 69, 61, .09); }
.s-tabela .ov-del::after { content: ""; position: absolute; left: 12px; right: 12px; top: 50%; height: 2px; background: var(--red); }
.s-tabela .ov-new { inset: 12px 8px 12px -6px; border-radius: 3px; background: var(--yellow-200); padding-left: 6px; gap: 12px; font: 500 21px/1 var(--mono); color: var(--ink); }
.s-tabela .ov-new em, .s-tabela .old { font: 500 17px/1 var(--sans); font-style: normal; }
.s-tabela .ov-new em { color: var(--yellow-700); }
.s-tabela .old { color: var(--red); }
.s-tabela .anoms { margin-top: 64px; display: grid; grid-template-columns: repeat(3, 1fr); column-gap: 32px; }
.s-tabela .anom { padding-top: 16px; border-top: 2px solid var(--red); }
.s-tabela .anom h3 { font: 600 30px/1.1 var(--sans); }
.s-tabela .anom h3 span { font-family: var(--cond); color: var(--red); margin-right: 12px; }
.s-tabela .anom p { margin-top: 16px; font: 400 25px/1.4 var(--sans); color: var(--ink-2); }

/* --- 11 formas normais -------------------------------------------------- */
.s-fn .stairs { position: absolute; inset: 0; display: grid; grid-template-columns: repeat(4, 1fr); column-gap: 32px; align-items: end; }
.s-fn .step { display: flex; flex-direction: column; padding: 32px; border-radius: 6px; background: var(--cream-2); }
.s-fn .step:nth-child(1) { height: 60%; }
.s-fn .step:nth-child(2) { height: 73%; }
.s-fn .step:nth-child(3) { height: 86%; }
.s-fn .step:nth-child(4) { height: 100%; }
.s-fn .nf { font: 600 96px/1 var(--cond); letter-spacing: -.01em; color: var(--green-700); }
.s-fn .rule-name { margin-top: 16px; font: 600 26px/1.2 var(--sans); }
.s-fn .did { margin-top: auto; padding-top: 24px; border-top: 1px solid var(--rule); font: 400 22px/1.38 var(--sans); color: var(--ink-2); }
.s-fn .step.hot { background: var(--blue); color: #fff; }
.s-fn .step.hot .nf { color: #fff; }
.s-fn .step.hot .did { color: #E1EAF5; border-top-color: rgba(255, 255, 255, .3); }
.s-fn .step.goal { background: transparent; box-shadow: inset 0 0 0 2px var(--rule); color: var(--muted); }
.s-fn .step.goal .nf { color: var(--faint); }
.s-fn .step.goal .did { color: var(--muted); }

/* --- 12 CEP ------------------------------------------------------------- */
.s-cep .dep { display: flex; align-items: baseline; gap: 16px; font: 500 30px/1.2 var(--mono); }
.s-cep .dep i { font-style: normal; color: var(--muted); }
.s-cep .dep .cep { color: var(--blue); font-weight: 600; }
.s-cep .dep .why { margin-left: 16px; font: 400 22px/1.2 var(--sans); color: var(--muted); }
.s-cep .schemas { margin-top: 40px; display: grid; grid-template-columns: 420px 96px 420px 420px; column-gap: 32px; align-items: start; }
.s-cep .schema { border-radius: 6px; background: #fff; box-shadow: inset 0 0 0 1px var(--rule); overflow: hidden; }
.s-cep .schema h4 { margin: 0; display: flex; justify-content: space-between; align-items: baseline; padding: 16px 24px; background: var(--cream-2); font: 600 21px/1.2 var(--mono); }
.s-cep .schema h4 span { font: 500 17px/1 var(--sans); color: var(--muted); }
.s-cep .schema.new h4 { background: var(--blue); color: #fff; }
.s-cep .schema.new h4 span { color: #DCE6F2; }
.s-cep .schema ul { padding: 8px 0; }
.s-cep .schema li { display: flex; justify-content: space-between; padding: 6px 24px; font: 400 19px/1.3 var(--mono); }
.s-cep .schema li em { font: 500 15px/1.3 var(--mono); font-style: normal; color: var(--muted); }
.s-cep .schema li.moved { color: var(--red); text-decoration: line-through; text-decoration-thickness: 2px; }
.s-cep .schema li.fk { color: var(--blue); font-weight: 600; }
.s-cep .between { align-self: center; text-align: center; font: 500 48px/1 var(--sans); color: var(--muted); }
.s-cep .between small { display: block; margin-top: 8px; font: 600 18px/1 var(--cond); letter-spacing: .04em; }
.s-cep .outcome { position: absolute; left: 0; right: 0; bottom: 0; padding-top: 24px; border-top: 1px solid var(--ink); }
.s-cep .outcome .bcnf { grid-column: 1 / span 4; display: flex; align-items: center; gap: 24px; }
.s-cep .outcome .bcnf b { font: 600 64px/1 var(--cond); color: var(--green-700); }
.s-cep .outcome .bcnf span { font: 400 22px/1.3 var(--sans); color: var(--ink-2); }
.s-cep .outcome .kept { grid-column: 6 / span 7; font: 400 22px/1.4 var(--sans); color: var(--ink-2); }
.s-cep .outcome .kept b { display: block; margin-bottom: 4px; color: var(--ink); font-size: 22px; }

/* --- 14 SQL ------------------------------------------------------------- */
.s-sql .code-col { grid-column: 1 / span 8; }
.s-sql pre {
  margin-top: 16px;
  padding: 24px 20px;
  border-radius: 6px;
  background: #0A1410;
  box-shadow: inset 0 0 0 1px var(--night-rule);
  font: 400 20px/1.62 var(--mono);
  color: #C9DBD1;
}
.s-sql .ln { position: relative; display: block; padding: 0 8px; white-space: pre; }
.s-sql .blk { position: relative; display: block; }
.s-sql .blk .hl { position: absolute; inset: 0; border-radius: 3px; background: rgba(245, 183, 0, .13); }
.s-sql .kw { color: #9CC0EA; }
.s-sql .ty { color: #96CAB6; }
.s-sql .st { color: #F2C77A; }
.s-sql .ln.cm { color: var(--yellow); }
.s-sql .counts { grid-column: 10 / span 3; align-self: start; margin-top: 39px; border-top: 1px solid var(--night-text); }
.s-sql .counts div { display: flex; justify-content: space-between; align-items: baseline; padding: 16px 0 12px; border-bottom: 1px solid var(--night-rule); }
.s-sql .counts dt { font: 500 19px/1 var(--mono); color: var(--night-muted); }
.s-sql .counts dd { font: 600 64px/1 var(--cond); color: #fff; }
.s-sql .counts div.idx dd { color: var(--yellow); }

/* --- 15 encerramento ---------------------------------------------------- */
.s-fim .brand { display: flex; align-items: center; gap: 16px; font: 600 24px/1 var(--sans); }
.s-fim .brand svg { width: 46px; height: 32px; }
.s-fim .from { margin-top: 88px; font: 400 32px/1.2 var(--sans); color: #C6E6D7; }
.s-fim .from s { text-decoration-thickness: 2px; }
.s-fim .to { margin-top: 12px; max-width: 1240px; font: 500 44px/1.2 var(--sans); }
.s-fim .thanks { margin-top: 56px; font: 600 220px/.86 var(--cond); letter-spacing: -.02em; }
.s-fim .repo { margin-top: 72px; font: 500 24px/1.2 var(--mono); color: #DDF0E7; }
.s-fim .team { position: absolute; left: 128px; right: 128px; bottom: 64px; display: grid; grid-template-columns: repeat(5, 1fr); column-gap: 32px; padding-top: 32px; border-top: 1px solid rgba(255, 255, 255, .3); }
.s-fim .member img { width: 72px; height: 72px; }
